function Total({ order }) {
  order.total = order.total * 1.2;  // never do this
  return <p>{order.total}</p>;
}

function Total({ order }) {
  const withTax = order.total * 1.2;  // derive a new value instead
  return <p>{withTax}</p>;
}

function Parent() {
  const [count, setCount] = useState(0);
  return <Child count={count} onIncrement={() => setCount(count + 1)} />;
}

function Child({ count, onIncrement }) {
  return <button onClick={onIncrement}>Clicked {count} times</button>;
}

function Avatar({ user }) {
  return <img className="avatar" src={user.imageUrl} alt={user.name} />;
}

function UserRow({ user }) {
  return (
    <li className="user-row">
      <Avatar user={user} />
      <span>{user.name}</span>
    </li>
  );
}

function UserList({ users }) {
  return (
    <ul>
      {users.map((user) => (
        <UserRow key={user.id} user={user} />
      ))}
    </ul>
  );
}

// Wrong: Inner is redefined on every render of Outer
function Outer() {
  function Inner() {
    return <p>Hi</p>;
  }
  return <Inner />;
}

// Right: declare both at module level
function Inner() {
  return <p>Hi</p>;
}

function Outer() {
  return <Inner />;
}

function Card({ title, children }) {
  return (
    <section className="card">
      <h3>{title}</h3>
      <div className="card-body">{children}</div>
    </section>
  );
}

<Card title="Account">
